gSt(){return"\u062d\u0630\u0641 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0628\u0646\u0643\u064a\u061f"},
Ss(a){return'\u0633\u064a\u0624\u062f\u064a \u0647\u0630\u0627 \u0625\u0644\u0649 \u062d\u0630\u0641 "'+a+'" \u0646\u0647\u0627\u0626\u064a\u0627\u064b. \u0644\u0627 \u064a\u0645\u0643\u0646 \u062d\u0630\u0641 \u0625\u0644\u0627 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u062a\u064a \u0644\u064a\u0633 \u0644\u0647\u0627 \u0633\u062c\u0644 \u0645\u0639\u0627\u0645\u0644\u0627\u062a \u2014 \u0623\u0645\u0627 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0630\u0627\u062a \u0627\u0644\u0633\u062c\u0644 \u0641\u064a\u0645\u0643\u0646 \u0625\u0644\u063a\u0627\u0621 \u062a\u0641\u0639\u064a\u0644\u0647\u0627 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0630\u0644\u0643.'},
gBV(){return"\u0627\u0644\u0645\u0648\u0638\u0641\u0648\u0646 \u0648\u0627\u0644\u0623\u062f\u0648\u0627\u0631"},
gOQ(){return"\u064a\u0645\u0643\u0646 \u0644\u0644\u0645\u0627\u0644\u0643 \u0641\u0642\u0637 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646."},
gFQ(){return"\u0625\u0636\u0627\u0641\u0629 \u0639\u0636\u0648 \u0641\u0631\u064a\u0642"},
P0(a){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0631\u0645\u0632 "+a+"\u061f"},
gP_(){return"\u0633\u064a\u064f\u0637\u0644\u0628 \u0645\u0646\u0647\u0645 \u062a\u0639\u064a\u064a\u0646 \u0631\u0645\u0632 \u062c\u062f\u064a\u062f \u062a\u0645\u0627\u0645\u064b\u0627 \u0641\u064a \u0627\u0644\u0645\u0631\u0629 \u0627\u0644\u0642\u0627\u062f\u0645\u0629 \u0627\u0644\u062a\u064a \u064a\u0633\u062c\u0644\u0648\u0646 \u0641\u064a\u0647\u0627 \u0627\u0644\u062f\u062e\u0648\u0644. \u064a\u062a\u0648\u0642\u0641 \u0631\u0645\u0632\u0647\u0645 \u0627\u0644\u062d\u0627\u0644\u064a \u0639\u0646 \u0627\u0644\u0639\u0645\u0644 \u0641\u0648\u0631\u064b\u0627."},
