gN1(){return"\u0623\u0646\u0634\u0626 \u0639\u0631\u0636 \u0633\u0639\u0631\u060c \u0623\u0648 \u0623\u0635\u062f\u0631 \u0641\u0627\u062a\u0648\u0631\u0629\u060c \u0623\u0648 \u062a\u062d\u0642\u0642 \u0645\u0646 \u0639\u0645\u0648\u0644\u062a\u0643."},
gBO(){return"\u0639\u0645\u0648\u0644\u062a\u064a"},
Ps(a){return A.ch(a,null,this.a,null,"\u062a\u0648\u0635\u064a\u0644\u0629 \u0648\u0627\u062d\u062f\u0629 \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u062a\u0639\u064a\u064a\u0646",""+a+" \u062a\u0648\u0635\u064a\u0644\u0627\u062a \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u062a\u0639\u064a\u064a\u0646",null,"\u0644\u0627 \u062a\u0648\u062c\u062f \u062a\u0648\u0635\u064a\u0644\u0627\u062a \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u062a\u0639\u064a\u064a\u0646")},
gPt(){return"\u0639\u064a\u0651\u0646 \u0643\u0644 \u062a\u0648\u0635\u064a\u0644\u0629 \u0644\u0633\u0627\u0626\u0642 \u0623\u0648 \u0645\u0646\u062f\u0648\u0628 \u0645\u0628\u064a\u0639\u0627\u062a \u0644\u064a\u0639\u0631\u0641 \u0645\u0627\u0630\u0627 \u064a\u0648\u0635\u0651\u0644 \u0627\u0644\u064a\u0648\u0645."},
gMJ(){return"\u0627\u0644\u0630\u0647\u0627\u0628 \u0625\u0644\u0649 \u0627\u0644\u062a\u0648\u0635\u064a\u0644\u0627\u062a"},
gKQ(){return"\u062f\u0645\u062c \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a"},
