gKP(){return"\u0646\u0641\u0633 \u0631\u0642\u0645 \u0627\u0644\u0647\u0627\u062a\u0641 \u0645\u0633\u062c\u0644"},
gKO(){return"\u0646\u0641\u0633 \u0627\u0644\u0627\u0633\u0645 \u0645\u0633\u062c\u0644"},
gBi(){return"\u0627\u0633\u062a\u062e\u062f\u0645 \u0647\u0630\u0647"},
KL(a,b){return"\u062f\u0645\u062c "+a+" \u0641\u064a "+b+"\u061f"},
KN(a,b){return"\u062a\u0645 \u062f\u0645\u062c "+a+" \u0641\u064a "+b+"."},
